-- Generated by `chainindex dbt` from chains/base.yaml and abis/AerodromeCLPool.json. Do not edit: change the chain file or ABI and regenerate.
-- Burn(address,int24,int24,uint128,uint256,uint256)
{{ config(
    materialized='view',
    schema='events_base',
    alias='aerodrome_cl_pool__burn',
    tags=['chains', 'chain_base'],
) }}

select
    toUInt64(8453) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    concat('0x', substring(substring(topic1, 3, 64), 25, 40)) as owner,
    toInt32(reinterpretAsInt256(reverse(unhex(substring(topic2, 3, 64))))) as tick_lower,
    toInt32(reinterpretAsInt256(reverse(unhex(substring(topic3, 3, 64))))) as tick_upper,
    toUInt128(reinterpretAsUInt256(reverse(unhex(substring(data, 3, 64))))) as amount,
    reinterpretAsUInt256(reverse(unhex(substring(data, 67, 64)))) as amount0,
    reinterpretAsUInt256(reverse(unhex(substring(data, 131, 64)))) as amount1
from {{ source('chain_base', 'logs') }}
where topic0 = '0x0c396cd989a39f4459b5fa1aed6a9a8dcdbc45908acfd67e028cd568da98982c'
  and address in (select address from {{ ref('base__contracts') }} where contract = 'aerodrome_cl_pool')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_base', 'orphaned_blocks') }}
  )
